        for line in metrics.read_text(encoding="utf-8", errors="replace").splitlines():
            try:
                row = json.loads(line)
            except ValueError:
                continue
            if row.get("event") == "train" and row.get("epoch"):
                last_epoch = max(last_epoch, int(row["epoch"]))
    except OSError:
        return False
    """Read-only: where the Stage2 run for one tree stands. Starts nothing."""
    tree, problem = resolve_stage2_tree(source_dir)
    if tree is None:
        return {
            "status": "unknown",
            "refused": problem,
            "available_trees": [item.name for item in stage2_trees()],
        }
    entry, _ = tree_entrypoint(tree)
    result_dir = tree_result_dir(tree)
    state = load_state(f"stage2__{tree.name}")
